package com.example.library;
import com.example.library.entity.*;import com.example.library.repository.*;import com.example.library.service.HomeSelectionService;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.LocalDate;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:home_test;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.database-platform=org.hibernate.dialect.H2Dialect","spring.jpa.hibernate.ddl-auto=create-drop","app.seed.enabled=false"}) @AutoConfigureMockMvc @Transactional
class HomeSelectionIntegrationTest {
 @Autowired HomeSelectionService home;@Autowired BookRepository books;@Autowired UserRepository users;@Autowired FavoriteRepository favorites;@Autowired BookReviewRepository reviews;@Autowired LoanRepository loans;@Autowired LoanItemRepository items;@Autowired MockMvc mvc;
 Book book(String title,int price,int quantity){return books.save(Book.builder().title(title).rentalPrice(BigDecimal.valueOf(price)).salePrice(BigDecimal.valueOf(90000)).totalQuantity(quantity).availableQuantity(quantity).status(quantity>0?BookStatus.AVAILABLE:BookStatus.OUT_OF_STOCK).build());}
 @Test void shelvesUseRealAggregatesAndExcludeUnavailableBudgetBooks() throws Exception {
  var first=book("First",20000,2);var cheap=book("Cheap",5000,1);var newest=book("Unavailable",1000,0);var user=users.save(User.builder().email("home@test.com").fullName("Home User").password("unused").build());
  favorites.save(Favorite.builder().book(cheap).user(user).build());reviews.save(BookReview.builder().book(first).user(user).rating(4).build());reviews.save(BookReview.builder().book(cheap).user(user).rating(5).build());
  var loan=loans.save(Loan.builder().user(user).borrowDate(LocalDate.now()).dueDate(LocalDate.now().plusDays(14)).rentalFee(BigDecimal.valueOf(40000)).status(LoanStatus.BORROWED).build());items.save(LoanItem.builder().loan(loan).book(first).quantity(2).rentalPrice(BigDecimal.valueOf(20000)).build());
  var result=home.get();assertEquals(newest.getId(),result.newBooks().get(0).book().getId());assertEquals(first.getId(),result.popularBooks().get(0).book().getId());assertEquals(2,result.popularBooks().get(0).borrowCount());assertEquals(cheap.getId(),result.topRatedBooks().get(0).book().getId());assertEquals(5.0,result.topRatedBooks().get(0).averageRating());assertEquals(cheap.getId(),result.budgetBooks().get(0).book().getId());assertEquals(2,result.budgetBooks().size());
  mvc.perform(get("/api/v1/books/home-selections")).andExpect(status().isOk()).andExpect(jsonPath("$.totalBooks").value(3)).andExpect(jsonPath("$.popularBooks[0].borrowCount").value(2)).andExpect(jsonPath("$.popularBooks[0].user").doesNotExist());
 }
 @Test void emptyStatisticsAreNotInventedAndSectionsHaveAtMostFourBooks(){for(int i=0;i<7;i++)book("Book "+i,5000+i,1);var result=home.get();assertEquals(4,result.newBooks().size());assertEquals(4,result.budgetBooks().size());assertTrue(result.popularBooks().isEmpty());assertTrue(result.topRatedBooks().isEmpty());}
 @Test void emptyLibraryReturnsEmptySections(){var result=home.get();assertEquals(0,result.totalBooks());assertTrue(result.newBooks().isEmpty());assertTrue(result.budgetBooks().isEmpty());}
}
